import { observer } from 'mobx-react-lite';
import React, { useEffect } from 'react';
import { useLocation} from 'react-router-dom/cjs/react-router-dom';
import { useContext } from 'react';
import { Context } from '../index';
import { getBasket , delFromBasket} from '../http/basketAPI';
import { Button, Card, Col, Container, Form, Row } from 'react-bootstrap'
import { createOrder, getAllOrders } from '../http/orderAPI';

const Orders = observer(() => {
  const {order} = useContext(Context)

    useEffect(() =>{
      getAllOrders().then(data => order.setAllOrders(data))
    }, [])

  return (
    <Container className="min-vh-100 d-flex flex-sm-column justify-content-center align-items-center mt-3">
      {order.allOrders.map(oneOrder =>
        <Form key={oneOrder.id}>
          <Form.Group className="mb-3">
            <Form.Label>Disabled input</Form.Label>
            <Form.Control placeholder="Disabled input" disabled />
          </Form.Group>
          <Form.Group className="mb-3">
            <Form.Label>Disabled select menu</Form.Label>
            <Form.Select disabled>
            <option>Disabled select</option>
        </Form.Select>
      </Form.Group>
        </Form>
      )}
    </Container>
  );
});

export default Orders;
